INSERT INTO CLMENU_JAVA (ID, DESCRIZIONE,PAGINA,MENULINK,SOFTWARE,JSP,LAYOUTTESTI,VERTICALIZZAZIONE,SOFTWAREESCLUSI,LINK_STANDARD,TIPO_FUNZIONALITA) VALUES  (1008,'Domande da Frontend in compilazione','foarjdomande/list.htm?software=SOFTWARE','5S3','*','JAVA',0,NULL,'PR,FI,AB','foarjdomande/list.htm?software=SOFTWARE','S');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_HALLEY','URL_WS_DIZIONARIO','Inserire qui l''endpoint che indica il web service per fare le chiamate alle funzionalità di recupero dati relativo alle classifiche e uffici');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_HALLEY','USA_WS_CLASSIFICHE','Se = a 1 indica che le classifiche devono essere recuperate tramite web service messo a disposizione dal protocollo halley, altrimenti il sistema funzionerà in maniera standard, ossia mappando le varie classifiche direttamente sull''albero degli interventi. Questo parametro è direttamente legato al parametro URL_WS_DIZIONARIO, infatti se si decide di recuperare le classifiche da web service, deve ovviamente essere indicato anche l''end point del web service'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('AREA_RISERVATA','RETURN_TO_URL_PER_SERVIZI','Specifica l''url a cui tornare quando si accede all''Area Riservata tramite url parlante');
insert into VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) values('AREA_RISERVATA','CENTRO_SERVIZI','Se 1 vengono abilitate le funzionalità di Centro Servizi che permettono di attivare un intervento attraverso una url diretta con possibilità di configurare se è un servizio autenticato e chi è il destinatario del servizio (nodo BACKOFFICE , nodo PEC, altro nodo). Per l''accesso diretto ad un singolo servizio tramite url parlante configurare il parametro CENTRO_SERVIZI_URL_BREVI');
insert into VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) values('AREA_RISERVATA','CENTRO_SERVIZI_URL_BREVI','Ha valore solo se attivo il parametro CENTRO_SERVIZI. Se presente vincola l''accesso all''Area Riservata solo tramite url parlanti es. /servizi/servizio001');
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('BENVENUTO','../nuovaistanzabenvenuto/view.htm','Benvenuto','Le pagine che seguono rappresentano il percorso guidato per la presentazione on line di una istanza.<br />Il percorso per inviare la pratica on line è composto da una serie di step (schede).<br />In fondo a destra si trova la numerazione delle pagine e in nero viene evidenziato lo step che si sta compilando.','0',null,null,'1');
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('INFORMATIVA','../nuovaistanzainformativa/view.htm','Informativa privacy','INFORMATIVA AI SENSI DELL''ART. 13 DEL DECRETO LEGISLATIVO N. 196/2003, "CODICE IN MATERIA DI PROTEZIONE DEI DATI PERSONALI"
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('ANAGRAFE','../nuovaistanzaanagrafesingola/view.htm','Anagrafe','In questa scheda vanno inseriti tutti i soggetti, persone fisiche e giuridiche, coinvolti nella pratica che si sta presentando. I soggetti possono essere l''interessato, l''azienda coinvolta, l''intermediario ...','0','INTERVENTO','(null)','3');
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('LOCALIZZAZIONE','../nuovaistanzalocalizzazione/view.htm','Localizzazione','È possibile in questa sezione inserire nel campo "Indirizzo" la localizzazione dell''intervento. <br />Selezionare un indirizzo compreso nello stradario comunale dopo aver digitato nel campo "Denominazione" almeno due lettere della localizzazione, quindi completare l''indirizzo indicando il civico ed eventuali note.<br />Se l''intervento ricade in una zona ancora non censita digitare "NON DEFINITO" nel campo "Denominazione" e nel campo "Note" immettere una localizzazione di massima (frazione, zona, etc.)','0',null,null,'4'); 
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('INTERVENTO','../nuovaistanzaintervento/view.htm','Intervento','In questa sezione è possibile individuare l''attività della propria azienda secondo la classificazione adottata dallo sportello unico del comune','0',null,null,'5'); 
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('PROCEDIMENTI','../nuovaistanzaprocedimenti/view.htm','Procedimenti','In questa sezione è possibile attivare gli endoprocedimenti utili al completamento dell''istanza.<br />Gli endo-procedimenti già selezionati sono proposti dal sistema in base alla compilazione degli step precedenti.','0','INTERVENTO',null,'6');
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('ALLEGATI','../nuovaistanzaallegati/view.htm','Allegati','Gli allegati che riportano il simbolo (<b>*</b>) sono obbligatori. Sarà cura del richiedente o della persona incaricata allegare i documenti proposti nell''elenco. <br />Il bottone "Sfoglia" permette di cercare il documento da caricare , una volta selezionato cliccare sulla voce "Carica". <br />','0','INTERVENTO',null,'7'); 
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('SCHEDE','../nuovaistanzaschede/view.htm','Schede','...','0','INTERVENTO',null,'8');
Insert into FO_ARJ_STEPS_BASE (NOME_STEP,LINK_FUNZIONE,TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP,ORDINE_DEFAULT) values ('ONERI','../nuovaistanzaoneri/view.htm','Riepilogo diritti/oneri','Questa scheda riepiloga quanti diritti di istruttoria/oneri/bolli devono essere corrisposti con riferimento all''intervento e agli endoprocedimenti attivati.
INSERT INTO verticalizzazionibase(modulo, descrizione) VALUES('PROTOCOLLO_EGRAMMATA', 'Se attivato consente di eseguire la protocollazione con il protocollo EGRAMMATA, al momento non abbiamo a disposizioni ambienti di test.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'URL_PROTO', 'Indicare l''url del web service da contattare per eseguire l''inserimento di un protocollo con il sistema di protocollazione e-grammata');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'URL_LEGGI', 'Indicare l''url del web service da contattare per eseguire la lettura di un protocollo con il sistema di protocollazione e-grammata');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'USER_ID', 'Indicare qui l''userid dell''utente con cui invocare il sistema di protocollazione, le credenziali sono le stesse degli utenti già presenti nel software di protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'PASSWORD', 'Indicare qui la password dell''utente con cui invocare il sistema di protocollazione, le credenziali sono le stesse degli utenti già presenti nel software di protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'ID_UNITA', '[Facoltativo] Indica l''identificativo della postazione di lavoro dell''utente nel caso in cui l''utente stesso abbia più postazioni di lavoro, questo parametro è dello stesso tipo del parametro LIVELLI_UNITA, in questo caso è possibile usare indifferentemente uno o entrambi i parametri se richiesti.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'LIVELLI_UNITA', '[Facoltativo] Indica il livello della postazione di lavoro dell''utente nel caso in cui l''utente stesso abbia più postazioni di lavoro, questo parametro è dello stesso tipo del parametro ID_UNITA, in questo caso è possibile usare indifferentemente uno o entrambi i parametri se richiesti.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_EGRAMMATA', 'REGISTRO', 'Indicare il registro da usare per eseguire l''inserimento dei protocolli. Valori ammessi: PG=Protocollo Generale; PP=Protocollo Particolare; R=Repertorio; N=Corrispondenza non protocollata'); 
