INSERT INTO VERTICALIZZAZIONIBASE(MODULO, DESCRIZIONE) VALUES('GENERA_COD_PRATICA_TELEMATICA','Se attivata consente di generare il codice pratica telematica nella fase di inserimento dell''istanza nel caso questo non venga passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_SIGEDO','URL_CGI_UO','Se valorizzato indica l''url cgi da chiamare per ottenere l''uo in base all''utente corrente che effettua la protocollazione, questo sistema è stato studiato solamente per il Comune di Firenze perchè si verificava il caso che alcuni utenti, non facenti parte all''uo indicata nel parametro UO, non potevano leggere i protocolli, nemmeno se erano stati loro stessi a crearli. L''applicativo cgi è stato sviluppato da Fabio Lo Giudice del Comune di Firenze. In questo parametro va specificato l''url inserendo la stringa fino al parametro di querystring senza inserirne il valore, ad esempio: http://url_cgi_per_restituire_la_uo?MATRICOLA=');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO', 'DESCRIZIONE_ENTE', 'Indicare in questo parametro la descrizione dell''ente, ad esempio - COMUNE DI FIRENZE -, questo valore andrà preso in considerazione nel caso in cui, durante una lettura di un protocollo in partenza, non venga individuato l''ufficio (smistamento) mittente del protocollo stesso; in questo caso il mittente prenderà il valore inserito in questo parametro'); 
