INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES('PAYER_ADAPTER','USA_CODICEFISCALE_TECNICO','Valori possibili S o N. Se S allora il codice fiscale passato, utilizzato per recuperare le scadenze di pagamento, viene ricercato sia nel campo del richiedente (ISTANZE.CODICERICHIEDENTE) che in quello del tecnico dell''istanza (ISTANZE.CODICEPROFESSIONISTA). Di default (se valore vuoto o non presente) il codice fiscale viene ricercato solamente in quello del richiedente dell''istanza (ISTANZE.CODICERICHIEDENTE).');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE)VALUES('PAYER_ADAPTER','TIPOLOGIA_SERVIZIO','Indica il valore che viene inviato da PayER nel tag RequestResponseLista.tipologiaServizio e RecuperaDatiBollettinoResponse.tipologiaServizio. Il valore deve essere concordato con Lepida e deve essere configurato obbligatoriamente.' );
