INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'IMPORT_XML_PEOPLE', 'I valori ammessi sono S o N. Se posto a S, nei documenti associati all''istanza viene inserito l''XML della pratica PEOPLE, se valorizzato a N o non valorizzato, tale file non viene inserito.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_ESPONENTE', 'Parametro per individuare l''esponente della localizzazione nella pratica people tramite identificativo XML_MOD');
