INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('TARES_BARI','URL_SERVIZIO','Indirizzo del web service dei servizi TARES');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('TARES_BARI','IDENTIFICATIVO_UTENTE','Nome utente da utilizzare per le chiamate al web service');
