INSERT INTO CLMENU_JAVA(ID,DESCRIZIONE,PAGINA,MENULINK,SOFTWARE,JSP,LAYOUTTESTI,VERTICALIZZAZIONE,SOFTWAREESCLUSI,LINK_STANDARD,TIPO_FUNZIONALITA) VALUES (1009,'Pannello gestione PEC','pecinbox/inbox.htm?software=SOFTWARE','109','*','JAVA',0,NULL, 'PR,FI,AB','pecinbox/inbox.htm?software=SOFTWARE','E');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES('NLA-RICEZIONE-PEC','INVIA_EVENTO_N_MSG_NONLETTI','Dopo ogni processamento se non presente (o = S) viene inserito un evento che riporta in descrizione il numero di messaggi da leggere presenti nella casella PEC alla in cui è stata eseguita la funzionalità di processaMessaggi');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES ('PROTOCOLLO_ATTIVO','COD_ALBERO_ROOT_PROTOCOLL','E'' il codice della voce d''albero degli interventi che la funzionalita'' "Pannello Gestione PEC" usa per recuperare la root per la creazione del controllo di selezione Intervento. Se non indicato o nullo vengono selezionate tutte le voci.');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'Se attivato, consente di eseguire la protocollazione con il protocollo FOLIUM, questo protocollo è gestito dalla ditta DedaGroup ed è presente al Comune di Carmignano, non è stato fornito alcun ambiente di test, ma, modificando il registro (parametro registro) si può accedere ad un eventuale ambiente di test creato dal cliente.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'URL', '(Obbligatorio) Indicare qui l''indirizzo del web service di protocollazione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'REGISTRO', 'Inserire il valore del registro da utilizzare in fase di inserimento protocollo e in fase di lettura protocollo, il valore inserito può discriminare un ambiente di test da quello di produzione, se non specificato automaticamente sarà utilizzato l''ambiente di produzione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'USERNAME', '(Obbligatorio) Username di autenticazione ad ogni metodo del web service del protocollo FOLIUM. Ogni metodo del web service infatti richiede come parametro fisso anche la classe WSAuthentication nella quale deve essere specificata la proprietà username che corrisponderà a questo parametro.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'PASSWORD', '(Obbligatorio) Password di autenticazione ad ogni metodo del web service del protocollo FOLIUM. Ogni metodo del web service infatti richiede come parametro fisso anche la classe WSAuthentication nella quale deve essere specificata la proprietà password che corrisponderà a questo parametro.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'CODICE_ENTE', '(Obbligatorio) Codice Ente di autenticazione ad ogni metodo del web service del protocollo FOLIUM. Ogni metodo del web service infatti richiede come parametro fisso anche la classe WSAuthentication nella quale deve essere specificata la proprietà codiceente che corrisponderà a questo parametro.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'APPLICAZIONE', '(Obbligatorio) Applicazione chiamante al web service, questo parametro fa parte dell''autenticazione che viene invocata ad ogni metodo del web service del protocollo FOLIUM. Ogni metodo del web service infatti richiede come parametro fisso anche la classe WSAuthentication nella quale deve essere specificata la proprietà applicazione che corrisponderà a questo parametro.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'AOO', '(Obbligatorio) Codice Aoo, questo parametro fa parte dell''autenticazione che viene invocata ad ogni metodo del web service del protocollo FOLIUM. Ogni metodo del web service infatti richiede come parametro fisso anche la classe WSAuthentication nella quale deve essere specificata la proprietà aoo che corrisponderà a questo parametro.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'BINDING', 'Indicare in questo parametro il nome del binding che il componente client deve usare per creare la connessione al web service, se non non valorizzato verrà usato quello di default (defaultHttpBinding)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'CODICE_CC', 'Indica il codice per conoscenza da utilizzare in fase di protocollazione. Sulla maschera di protocollazione è presente un campo a tendina denominato -Trasmesso per- legato all''anagrafica (Mittente / Destinatario), questo campo viene popolato dai valori presenti nella tabella PROTOCOLLO_MODALITAINVIO, indicando il codice in questo campo, quando l''operatore selezionerà nella tendina -Trasmesso per- il valore con lo stesso codice, l''anagrafica selezionata sarà considerata per conoscenza. Se non valorizzato il destinatario (mittente) del protocollo non sarà mai per conoscenza.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCPRO', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCAREA', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_HALLEY', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO', 'CODICEAMMINISTRAZIONE', 'Indicare in questo parametro il Codice dell''amministrazione, questo dato andrà a valorizzare gli elementi CODICEAMMINISTRAZIONE della segnatura che viene inviata al metodo protocollazione del web service. Se non valorizzato questo dato verrà preso dal parametro CODICEENTE come succedeva in passato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'CHECK_REPLY', 'I valori ammessi sono S o N. Se posto a S per ogni PEC presente nella INBOX controlla se si tratta di una Reply-to relativa ad una PEC inviata da VBG (ed in caso positivo genera il contromovimento associato al movimento da cui era stata inviata la PEC). Se posto a N o non valorizzato non vengono elaborate tali tipologie di PEC.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_FOLIUM', 'USA_WSCLASSIFICHE', 'Indica se per il recupero delle classifiche, sull''albero degli interventi, debba essere usato l''apposito metodo messo a disposizione dal web service (valore = 1) oppure no (valore 0, vuoto o non presente).');
